document.querySelectorAll('[data-open]').forEach(b=>{if(b.classList.contains('desktop-icon')){b.addEventListener('click',()=>{document.querySelectorAll('.desktop-icon').forEach(x=>x.classList.toggle('selected',x===b));if(matchMedia('(pointer:coarse)').matches)open(b.dataset.open)});b.addEventListener('dblclick',()=>open(b.dataset.open));b.addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();open(b.dataset.open)}})}else b.onclick=()=>open(b.dataset.open)});
